import { Task, TaskStatus } from '../domain/Task';
import { TaskRepository } from '../domain/TaskRepository';

export class InMemoryTaskRepository implements TaskRepository {
  private tasks = new Map<string, Task>();

  save(task: Task): void {
    this.tasks.set(task.id, task);
  }

  getById(id: string): Task | null {
    return this.tasks.get(id) ?? null;
  }

  getByProjectId(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter((t) => t.projectId === projectId);
  }

  getByProjectIdAndStatus(projectId: string, status: TaskStatus): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.projectId === projectId && t.status === status,
    );
  }

  getByProjectIdAndAssignee(projectId: string, assigneeId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.projectId === projectId && t.assigneeId === assigneeId,
    );
  }
}

