import express, { Express } from 'express';
import { AddTaskUseCase } from '../application/AddTaskUseCase';
import { AssignTaskUseCase } from '../application/AssignTaskUseCase';
import { CreateProjectUseCase } from '../application/CreateProjectUseCase';
import { CreateUserUseCase } from '../application/CreateUserUseCase';
import { ListTasksUseCase } from '../application/ListTasksUseCase';
import { MarkTaskDoneUseCase } from '../application/MarkTaskDoneUseCase';
import { InMemoryProjectRepository } from './InMemoryProjectRepository';
import { InMemoryTaskRepository } from './InMemoryTaskRepository';
import { InMemoryUserRepository } from './InMemoryUserRepository';
import { ProjectController } from './ProjectController';
import { TaskController } from './TaskController';
import { UserController } from './UserController';

export function createApp(): Express {
  const app = express();

  app.use(express.json());

  const userRepository = new InMemoryUserRepository();
  const projectRepository = new InMemoryProjectRepository();
  const taskRepository = new InMemoryTaskRepository();

  const createUserUseCase = new CreateUserUseCase(userRepository);
  const createProjectUseCase = new CreateProjectUseCase(projectRepository);
  const addTaskUseCase = new AddTaskUseCase(taskRepository);
  const assignTaskUseCase = new AssignTaskUseCase(taskRepository, userRepository);
  const listTasksUseCase = new ListTasksUseCase(taskRepository);
  const markTaskDoneUseCase = new MarkTaskDoneUseCase(taskRepository);

  const userController = new UserController(createUserUseCase);
  const projectController = new ProjectController(createProjectUseCase);
  const taskController = new TaskController(
    addTaskUseCase,
    assignTaskUseCase,
    listTasksUseCase,
    markTaskDoneUseCase,
  );

  app.post('/users', (req, res) => userController.create(req, res));
  app.post('/projects', (req, res) => projectController.create(req, res));
  app.post('/tasks', (req, res) => taskController.add(req, res));
  app.get('/projects/:projectId/tasks', (req, res) => taskController.list(req, res));
  app.post('/tasks/assign', (req, res) => taskController.assign(req, res));
  app.post('/tasks/mark-done', (req, res) => taskController.markDone(req, res));

  return app;
}

